// === Tab: mySketch.js ===
let x, y;
let a, b, c, d;
let points = [];
let limit;
let colors1 = ['#f23b52', '#f3262e', '#f1060f'];
let colors2 = ['#0534f2', '#1e46ea', '#2042cb'];
let colors3 = ['#f8cd2b', '#f4c618', '#fcc703'];

let encoder;
const frate = 30; // frame rate
const numFrames = 1800; // num of frames to record
let recording = false;
let recordedFrames = 0;

function preload() {
	w = 800;
	h = 800;
	HME.createH264MP4Encoder().then(enc => {
			encoder = enc
			encoder.outputFilename = 'test'
			encoder.width = 2*w
			encoder.height = 2*h
			encoder.frameRate = frate
			encoder.kbps = 50000 // video quality
			encoder.groupOfPictures = 10 // lower if you have fast actions.
			encoder.initialize()
	})
}

function setup() {
	createCanvas(w, h);
	frameRate(frate);
	background('white');

	// Clifford Attractor
	a = -1.4; b = 1.6; c = 1.0; d = 0.7;

	limit = 1;
	for(let i = 0; i < limit; i += 1) {
		points.push({
			x: width/2,
			y: 5*i + height/2, 
			vx: 0,
			vy: 0
		})
	}
}

function draw() {
	for(let i = 0; i < points.length; i++) {
    // get each point and do what we did before with a single point
    let p = points[i];

    let value = getValue(p.x, p.y);
    p.vx += cos(value) * 0.3;
  	p.vy += sin(value) * 0.3;

		x = p.x + p.vx;
		y = p.y + p.vy;

		strokeWeight(5);
		if((value >= -1)&&(value <= 1)){
			stroke(random(colors1));
		} else if(value > 1) {
			stroke(random(colors2));
		} else if(value < -1) {
			stroke(random(colors3));
		} 

		line(p.x, p.y, x, y);

    // add velocity to position and line to new position
    p.x += p.vx;
    p.y += p.vy;

    // apply some friction so point doesn't speed up too much
    p.vx *= 0.99;
    p.vy *= 0.99;

    // wrap around edges of screen
    if(p.x > width) p.x = 0;
		if(p.y > height) p.y = 0;

		if(p.x < 0) p.x = width;
		if(p.y < 0) p.y = height;
  }

		// keep adding new frame
	if (recording) {
			encoder.addFrameRgba(drawingContext.getImageData(0, 0, encoder.width, encoder.height).data);
			recordedFrames++;
	}
	// finalize encoding and export as mp4
	if (recordedFrames === numFrames) {
			recording = false;
			recordedFrames = 0;

			encoder.finalize()
			const uint8Array = encoder.FS.readFile(encoder.outputFilename);
			const anchor = document.createElement('a');
			anchor.href = URL.createObjectURL(new Blob([uint8Array], { type: 'video/mp4' }));
			anchor.download = encoder.outputFilename;
			anchor.click();
			encoder.delete();

			preload(); // reinitialize encoder
	}
}

function getValue(x, y) {
	let scale = 0.01;
  x = (x - width / 2) * scale;
  y = (y - height / 2)  * scale;

  // Clifford attactor gives new x, y for old one. 
  let x1 = sin(a * y) + (c * cos(a * x));
  let y1 = sin(b * x) + (d * cos(b * y));

  // find angle from old to new. that's the value.
	return atan2(y1 - y, x1 - x);
}

function mouseClicked() { 
  if(recording == false) {
		recording = true;
	} else {
		recording = false;
	} 
}

